#include <stddef.h>
#include <stdint.h>

/* pcre3 API types */
typedef struct pcre pcre;
typedef struct pcre_extra pcre_extra;

/* pcre2 API types */
typedef struct pcre2_code pcre2_code;
typedef struct pcre2_match_data pcre2_match_data;

/* pcre2 functions we need */
extern pcre2_code *pcre2_compile_8(const unsigned char *, int, uint32_t,
                                   int *, size_t *);
extern void pcre2_code_free_8(pcre2_code *);
extern int pcre2_match_8(const pcre2_code *, const unsigned char *, size_t,
                         size_t, uint32_t, pcre2_match_data *,
                         void *);
extern pcre2_match_data *pcre2_match_data_create_from_pattern_8(
    const pcre2_code *, void *);
extern void pcre2_match_data_free_8(pcre2_match_data *);
extern size_t pcre2_get_ovector_count_8(pcre2_match_data *);
extern size_t *pcre2_get_ovector_pointer_8(pcre2_match_data *);
extern int pcre2_get_error_message_8(int, unsigned char *, size_t);

/* pcre3 compatibility - pcre_free is a variable, not a function */
void *pcre_free = NULL;

/* pcre_compile2 - wraps pcre2_compile_8 */
pcre *pcre_compile2(const char *pattern, int options, int *errorcodeptr,
                     const char **errptr, int *erroffset,
                     const unsigned char *tableptr) {
    (void)tableptr;
    uint32_t pcre2_options = 0;
    int errcode;
    size_t erroff;

    /* Map pcre3 options to pcre2 options - approximate */
    /* pcre3: PCRE_CASELESS=1, PCRE_MULTILINE=2, PCRE_DOTALL=4, etc. */
    if (options & 1) pcre2_options |= 0x00000008u; /* PCRE2_CASELESS */
    if (options & 2) pcre2_options |= 0x00000400u; /* PCRE2_MULTILINE */
    if (options & 4) pcre2_options |= 0x00000020u; /* PCRE2_DOTALL */
    if (options & 8) pcre2_options |= 0x00000002u; /* PCRE2_EXTENDED */
    if (options & 0x800) pcre2_options |= 0x00000001u; /* PCRE2_ANCHORED */

    pcre2_code *re = pcre2_compile_8((const unsigned char *)pattern, -1,
                                     pcre2_options, &errcode, &erroff);
    if (!re) {
        if (errorcodeptr) *errorcodeptr = errcode;
        if (errptr) *errptr = "pcre2 compilation error";
        if (erroffset) *erroffset = (int)erroff;
        return NULL;
    }
    if (errorcodeptr) *errorcodeptr = 0;
    return (pcre *)re;
}

/* pcre_exec - wraps pcre2_match_8 */
int pcre_exec(const pcre *code, const pcre_extra *extra,
              const char *subject, int length, int startoffset,
              int options, int *ovector, int ovecsize) {
    (void)extra;
    uint32_t pcre2_options = 0;

    pcre2_match_data *md = pcre2_match_data_create_from_pattern_8(
        (const pcre2_code *)code, NULL);
    if (!md) return -1;

    int rc = pcre2_match_8((const pcre2_code *)code,
                           (const unsigned char *)subject,
                           (size_t)(length < 0 ? __builtin_strlen(subject) : length),
                           (size_t)startoffset,
                           pcre2_options, md, NULL);

    if (rc > 0) {
        size_t count = pcre2_get_ovector_count_8(md);
        size_t *ovec = pcre2_get_ovector_pointer_8(md);
        int max_pairs = ovecsize / 2;
        int i;
        for (i = 0; i < rc && i < max_pairs; i++) {
            ovector[2*i] = (int)ovec[2*i];
            ovector[2*i+1] = (int)ovec[2*i+1];
        }
    }

    pcre2_match_data_free_8(md);
    return rc;
}

